    sample_rate_hz INTEGER, 
    channels INTEGER, 
    bits_per_sample INTEGER, 
    cover_artwork_id INTEGER, 
    cover_source TEXT, 
    cover_relative_path TEXT, 
    CONSTRAINT pk_audio_files PRIMARY KEY (id), 
    CONSTRAINT uq_audio_files_library_id UNIQUE (library_id, relative_path), 
    CONSTRAINT ck_audio_files_supported_format CHECK (format IN ('FLAC', 'MP3')), 
    CONSTRAINT ck_audio_files_relative_path_nonempty CHECK (length(relative_path) > 0), 
    CONSTRAINT ck_audio_files_duration_nonnegative CHECK (duration_seconds IS NULL OR (typeof(duration_seconds) IN ('integer', 'real') AND duration_seconds >= 0)), 
